import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水风井","description":"周易折中 - 水风井","frontmatter":{"title":"水风井","description":"周易折中 - 水风井"},"headers":[],"relativePath":"zh/classics/zhezhong/054.md","filePath":"zh/classics/zhezhong/054.md"}'),h={name:"zh/classics/zhezhong/054.md"};function n(p,a,d,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="水风井" tabindex="-1">水风井 <a class="header-anchor" href="#水风井" aria-label="Permalink to “水风井”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈井序〉：“卦困乎上者必反下，故受之以井。承上升而不已必困为言，谓上井不已而困，则必反于下也。物之在下者莫如井，井所以次困也。为卦坎上巽下，坎水也，巽之象则木也，巽之义则入也。木器之象，木入于水下而上乎水，汲井之象也。”</p><p>井：改邑不改井，无丧无得，往来井井，汔至亦未繘井，羸其瓶凶</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>井者，穴地出水之处。以巽木入乎坎水之下，而上出其水，故为井。改邑不改井，故无丧无得，而往者来者皆井其井也。汔，几也；繘，绠也；羸，败也。汲井几至，未尽绠而败其瓶，则凶也。其占为事仍旧无得丧，而又当敬勉，不可几成而败也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>井之为物，常而不可改也。邑可改而之他，井不可迁也，故曰“改邑不改井”。汲之而不竭，存之而不盈，无丧无得也。至者皆得其用，往来井井也。无丧无得，其徳也常。往来井井，其用也周常也，周也，井之道也。汔，几也；繘，绠也。井以济用为功，几至而未及用，亦与未下繘于井同也。君子之道贵乎有成，所以五谷不熟不如荑稗，掘井九仞而不及泉犹为弃井。有济物之用而未及物，犹无有也。羸败其瓶而失之，其用丧矣，是以凶也。羸，毁败也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏康成曰 ：井以汲水，水无空竭，犹人君以政教养天下，惠泽无穷也。</p></li><li><p>丘氏富国曰 ：改邑不改井，井之体也；无丧无得，井之徳也。“往来井井，井井之用也”此三句言井之事；“汔至亦未繘井，未及于用也；羸其瓶，失其用也”此二句言汲井之事。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>改邑不改井，句解说多错文意，盖言所在之邑，其井皆无异制，如诸葛孔明行军之处，千井齐甃者，以喻王道之行，国不异政，家不殊俗也。无丧无得，则言井无盈涸，以喻道之可久。往来井井，则言所及者多，以喻道之可大。此三句皆言井在人事，则王者养民之政是也。然井能泽物而汲之者器，政能养民而行之者人。无器则水之功不能上行，无人则王者之泽不能下究。故“汔至”以下，又以汲井之事言之。</p><p>象曰：木上有水，井；君子以劳民劝相</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>木上有水，津润上行，井之象也。劳民者，以君养民；劝相者，使民相养，皆取井养之义。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>木承水而上之，乃器汲水而出，井之象。君子观井之象，法井之德，以劳徕其民而劝勉以相助之道也。劳徕其民，法井之用也；劝民使相助，法井之施也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：养而不穷，莫若劳民而劝相也。</p></li><li><p>杨氏绘曰 ：水性润下，能上润于物者，井之用也。</p></li><li><p>朱子语类云 ：木上有水，井。说者以为木是汲器，则后面却有瓶。瓶自是瓦器，只是说水之津润上行至那木之杪，这便是井水上行之象。 又云：草木之生津润皆上行，直至树末，便是木上有水之义。如菖蒲叶每晨叶尾皆有水如珠颗，虽藏之密室亦然，非露水也。问如此则井之义与木上有水何预？曰：木上有水，便如水本在井底，却能汲上来给人之食，故取象如此。</p></li><li><p>又云：草木之生津润皆上行，直至树末，便是木上有水之义。如菖蒲叶每晨叶尾皆有水如珠颗，虽藏之密室亦然，非露水也。问如此则井之义与木上有水何预？曰：木上有水，便如水本在井底，却能汲上来给人之食，故取象如此。</p></li><li><p>李氏心传曰 ：劝相即相友相助相扶持之意。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>大象“木上有水”，须以朱子之说为长。《彖传》“巽乎水而上水”，则郑氏桔槔之说不妨并存也。劳民者如巽风之布号令，劝相者如坎水之相灌输。</p><p>彖曰：巽乎水而上水，井井养而不穷也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦象释卦名义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏康成曰 ：坎水也，巽木，桔槔也。桔槔引瓶下入泉口，汲水而出，井之象也。</p></li><li><p>荀氏爽曰 ：木入水出，井之象也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>释名之下又著“井养而不穷也”一句，亦以起释辞之意。</p><p>改邑不改井，乃以刚中也；汔至，亦未繘井，未有功也；羸其瓶，是以凶也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦辞。“无丧无得，往来井井”两句意与“不改井”同，故不复出。刚中以二五而言。未有功而败其瓶，所以凶也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>巽入于水，下而上其水者，井也。井之养于物，不有穷已，取之而不竭，德有常也。邑可改，井不可迁，亦其德之常也。二五之爻，刚中之德，其常乃如是。卦之才与义合也。虽使几至既未为用，亦与未繘井同。井以济用为功，水出乃为用，未出则何功也？瓶所以上水而致用也，羸败其瓶，则不为用矣，是以凶也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：井井未尝有得丧，繘井之为功，羸瓶之为凶，在汲者尔。</p></li><li><p>晁氏说之曰 ：或谓彖主三阳言，五“寒泉食”，是阳刚居中，邑可改而井不可改也；三“井渫不食”，是未有功也；二“瓮敝漏”，是羸其瓶而凶者也。</p></li><li><p>郭氏雍曰 ：不言“无丧无得，往来井井”者，盖皆系乎刚中之德。圣人举一以明之耳。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>井惟有常，故其体则无丧无得，其用则往来井井。王道惟有常，故其体则久而无弊，其用则广而及物。故言“改邑不改井”，足以包下二者。</p><p>/books/106/48/1.html</p><p>初六 井泥不食，旧井无禽</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>井以阳刚为泉，上出为功。初六以阴居下，故为此象。盖井不泉而泥，则人所不食，而禽鸟亦莫之顾矣。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>井与鼎皆物也，就物以为义。六以阴柔居下，上无应援，无上水之象，不能济物，乃井之不可食也。井之不可食以泥污也，在井之下有泥之象。井之用以其水之养人也，无水则舍置不用矣。井水之上，人获其用，禽鸟亦就而求焉。旧废之井，人既不食水，不复上，则禽鸟亦不复往矣。盖无以济物也。井本济人之物，六以阴居下，无上水之象，故为不食。井之不食以泥也，犹人当济物之时而才弱无援，不能及物，为时所舍也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：最在井底，上又无应，沈滞滓秽，故曰“井泥不食”也。井泥而不可食，则是久井不见渫治者也。久井不见渫治，禽所不向，而况人乎？</p></li><li><p>蔡氏清曰 ：井以阳刚为泉，而初六则阴柔也，故为井泥、为旧井。井以上出为功，而初六则居下，故为不食、为无禽。</p></li></ul><p>象曰：井泥不食，下也；旧井无禽，时舍也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>言为时所弃。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>以阴而居井之下，泥之象也。无水而泥，人所不食也。人不食则水不上，无以及禽鸟，禽鸟亦不至矣。见其不能济物，为时所舍置不用也。若能及禽鸟，是亦有所济也。舍上声，与干之时舍音不同。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><p>孔氏颖逹曰 ：下也者，以其最在井下，故为井泥也。时舍也者，人既不食，禽亦不向，是一时共弃舍也。</p><p>九二：井谷射鲋，瓮敝漏</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>九二刚中有泉之象，然上无正应，下比初六，功不上行，故其象如此。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>二虽刚阳之才，而居下上无应，而比于初，不上而下之象也。井之道上行者也，㵎谷之水则旁出而就下。二居井而就下，失井之道，乃井而如谷也。井上出则养人而济物，今乃下就污泥注于鲋而已。鲋或以为虾，或以为蟆，井泥中微物耳。射，注也，如谷之下流注于鲋也。瓮敝漏，如瓮之破漏也。阳刚之才本可以养人济物，而上无应援，故不能上而就下，是以无济用之功。如水之在瓮，本可为用，乃破敝而漏之，不为用也。井之初二无功而不言悔咎，何也？曰：失则有悔，过则为咎。无应援而不能成用，非悔咎乎？居二比初，岂非过乎？曰：处中非过也，不能上由无援，非以比初也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏振渊曰 ：以井言，则为井谷之泉，仅下注于鲋；以汲井言，则为敝壊之瓮，水反漏于下也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>井谷者，井中出水之穴窍也。井能出水则非泥井也，而其功仅足以射鲋者，上无汲引之人，如瓶瓮之敝漏然，则不能自济于人用也，决矣。在卦则以井喻政，以汲之者喻行政之人；在爻则下体以井喻材徳之士，汲之者喻进用之君；上体以井喻徳位之君，汲之者喻被泽之众。三义相因而取喻不同。</p><p>象曰：井谷射鲋，无与也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>井以上出为功，二阳刚之才本可济用，以在下而上无应援，是以下比而射鲋。若上有与之者，则当汲引而上，成井之功矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><p>谷氏家杰曰 ：谓有泉而无与者与无泉而时弃者，自不可同也。</p><p>九三：井渫不食，为我心恻，可用汲，王明并受其福</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>渫，不停污也。井渫不食，而使人心恻，可用汲矣。王明则汲井以及物，而施者受者并受其福也。九三以阳居阳，在下之上而未为时用，故其象占如此。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>三以阳刚居得其正，是有济用之才者也。在井下之上，水之清洁可食者也。井以上为用，居下未得其用也。阳之性上，又志应上六，处刚而过中，汲汲于上进，乃有才用而切于施为。未得其用，则如井之渫治清洁而不见食，为心之恻怛也。三居井之时，刚而不中，故切于施为，异乎用之则行，舍之则藏者也。然明王用人岂求备也？故王明则受福矣。三之才足以济用，如井之清洁可用汲而食也。若上有明王，则当用之而得其效，贤才见用则已得行其道，君得享其功，下得被其泽，上下并受其福也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰 ：为我心恻，我指旁人，所谓行恻也，非谓九三自恻。也可用汲、带连王明并受其福，皆恻之之辞也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>不曰明王而曰王明，乃恻者祈祷之辞，言王若明，则吾侪并受其福矣。</p><p>象曰：井渫不食，行恻也；求王明，受福也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>行恻者，行道之人皆以为恻。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>井渫治而不见食，乃人有才知而不见用，以不得行为忧恻也。既以不得行为恻，则岂免有求也？故求王明而受福，志切于行也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏汝梅曰 ：井不以不食为忧，贤者不以不遇而恻。心恻者，行人也，行汲之人为之求王者之明也。求王之明，岂朋比以干禄？为其见知于上，则福被生民，犹井汲而出，然后利及于人也。</p></li><li><p>王氏申子曰 ：井渫而不为人所食，纵不自恻，行道之人亦为之恻然矣。纵不求人之我用，人亦为之求之，以并受其福矣。</p></li></ul><p>六四：井甃无咎</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以六居四，虽得其正，然阴柔不泉，则但能脩治而无及物之功，故其象为井甃，而占则无咎。占者能自脩治，则虽无及物之功，而亦可以无咎矣。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>四虽阴柔而处正，上承九五之君，才不足以广施利物，亦可自守者也。故能脩治则得无咎。甃，砌累也，谓脩治也。四虽才弱不能广济物之功，脩治其事不至于废可也。若不能脩治，废其养人之功，则失井之道，其咎大矣。居高位而得刚阳中正之君，但能处正承上不废其事，亦可以免咎也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>丘氏富国曰 ：三在内卦，渫井内以致其洁；四在外卦，甃井外以御其污。盖不渫则污者不洁，不甃则洁者易污。</p></li><li><p>来氏知徳曰 ：六四阴柔得正，近九五之君，盖脩治其井以潴蓄九五之寒泉者也。占者能脩治臣下之职，则可以因君而成井养之功，斯无咎矣。</p></li></ul><p>象曰：井甃无咎，脩井也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>甃者，脩治于井也。虽不能大其济物之功，亦能脩治不废也，故无咎。仅能免咎而已，若在刚阳，自不至如是，如是则可咎矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：脩治也，以瓦甓垒井称甃。</p></li><li><p>苏氏轼曰 ：脩洁也。阳为动为实，阴为静为虚。泉者，所以为井也，动也，实也。井者，泉之所寄也，静也，虚也。初六最下，故曰泥；上六最上，故曰收；六四居其闲而不失正，故曰甃。甃之于井，所以御恶而洁井也。井待是而洁，故无咎。</p></li></ul><p>九五：井洌寒泉，食</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>洌，洁也。阳刚中正，功及于物，故为此象。占者有其徳，则契其象也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>五以阳刚中正居尊位，其才其徳尽善尽羙。井洌寒泉，食也。洌谓甘洁也，井泉以寒为羙，甘洁之寒泉可为人食也。于井道为至善也。然而不言吉者，井以上出为成功，未至于上，未及用也，故至上而后言元吉。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>易氏祓曰 ：三与五皆泉之洁者。三居甃下，未汲之泉也，故曰“不食”。五出乎甃，已汲之泉也，故言“食”。</li></ul><p>象曰：寒泉之食，中正也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>寒泉而可食，井道之至善者也。九五中正之德，为至善之义。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>诗云：“泉之竭矣，不云自中。”盖不中，则源不常裕而不寒也。又云：“冽彼下泉，浸彼苞萧。”盖不正，则流不逮下而不食也。</p><p>上六：井收勿幕，有孚，元吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>收，汲取也（晁氏云：收，鹿卢收繘者也，亦通）。幕，蔽覆也。有孚，谓其出有源而不穷也。井以上出为功，而坎口不揜，故上六虽非阳刚，而其象如此。然占者应之，必有孚，乃元吉也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>井以上出为用，居井之上，井道之成也。收，汲取也；幕，蔽覆也。取而不蔽，其利无穷。井之施广矣大矣，有孚有常而不变也，博施而有常，大善之吉也。夫体井之用，博施而有常，非大人孰能？它卦之终为极、为变，唯井与鼎终乃为成功，是以吉也。</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>勿幕，谓取之无禁，所谓“往来井井”者也。有孚，谓有源不穷，所谓“无丧无得”者也。此爻得备卦之义者，巽乎水而上，水至此爻则上之极也。</p><p>象曰：元吉在上，大成也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>以大善之吉在卦之上，井道之大成也。井以上为成功。</p><p>总论</p><ul><li><p>李氏过曰 ：初井泥，二井谷，皆废井也；三井渫则渫初之泥；四井甃则甃二之谷。既渫且甃，井道全矣。故五井洌而泉寒，上井收而勿幕，功始及物而井道大成矣。</p></li><li><p>丘氏富国曰 ：先儒以三阳为泉，三阴为井，阳实阴虗之象也。九二言井谷射鲋，九三言井渫不食，九五言井洌寒泉，曰射、曰渫、曰洌，非泉之象乎？初六言井泥不食，六四言井甃无咎，上六言井收勿幕，曰泥、曰甃、曰收，非井之象乎？以卦序而言，则二之射始逹之泉也，三之渫已洁之泉也，五之洌则可食之泉矣。初之泥方掘之井也，四之甃已修之井也，上之收则已汲之井矣。又以二爻为一例，则初二皆在井下不见于用，故初为泥而二为谷；三四皆在井中将见于用，故三为渫而四为甃；五上皆在井上而已见于用矣，故五言食而上言收也。</p></li></ul>',118)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
